//! Saved local worlds and the open world's status as the launcher's world service reports them.

use bridge::{Backend, GameMode, WorldState};
use serde::{Deserialize, Serialize};

/// Terrain generator of a local world.
#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Generator {
    /// Natural terrain generated by the selected backend.
    #[default]
    Normal,
    Flat,
}

/// Difficulty of a local world.
#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Difficulty {
    Peaceful,
    Easy,
    #[default]
    Normal,
    Hard,
}

/// One saved local world.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct World {
    pub id: String,
    pub name: String,
    pub game_mode: GameMode,
    pub generator: Generator,
    pub difficulty: Difficulty,
    pub backend: Backend,
    pub seed: i64,
    pub options: super::options::WorldOptions,
    /// Its `level.dat` exceeds the read bound, so options are neither shown nor written.
    pub options_unavailable: bool,
    pub created_unix: i64,
    pub last_played_unix: i64,
    /// Bytes on disk.
    pub size_bytes: u64,
}

/// The size of a world's menu thumbnail, 16:9 like the list rows that show it.
pub const THUMBNAIL_SIZE: [u32; 2] = [320, 180];

/// A saved world's menu thumbnail: its last captured view, as an encoded image. Equal when
/// it names the same image, so comparing views never compares pixels.
#[derive(Clone, Debug)]
pub struct WorldThumbnail {
    /// The artwork key the menu draws it under.
    pub key: String,
    pub image: std::sync::Arc<[u8]>,
}

impl WorldThumbnail {
    /// The thumbnail of world `id` from its encoded `image`.
    #[must_use]
    pub fn new(id: &str, image: std::sync::Arc<[u8]>) -> Self {
        Self {
            key: thumbnail_key(id),
            image,
        }
    }
}

impl PartialEq for WorldThumbnail {
    fn eq(&self, other: &Self) -> bool {
        self.key == other.key && std::sync::Arc::ptr_eq(&self.image, &other.image)
    }
}

impl Eq for WorldThumbnail {}

/// The artwork key of world `id`'s thumbnail.
#[must_use]
pub fn thumbnail_key(id: &str) -> String {
    format!("world-thumbnail:{id}")
}

/// Settings changes for a saved world; `None` fields are left alone.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct WorldUpdate {
    pub name: Option<String>,
    pub game_mode: Option<GameMode>,
    pub difficulty: Option<Difficulty>,
    pub options: Option<super::options::OptionChanges>,
}

/// Settings for a new world; a `None` seed is random.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct NewWorld {
    pub name: String,
    pub game_mode: GameMode,
    pub generator: Generator,
    pub difficulty: Difficulty,
    /// `None` takes the default for this machine.
    pub backend: Option<Backend>,
    pub seed: Option<i64>,
    pub options: super::options::WorldOptions,
}

/// Why the dedicated-server backend cannot run.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum UnavailableReason {
    DockerMissing,
    DockerNotRunning,
}

/// Dedicated-server acquisition progress.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SetupState {
    Unsupported,
    EulaRequired,
    NotInstalled,
    /// Container runtime: probing the Docker daemon at open.
    CheckingRuntime,
    /// Container runtime: pulling the server image (layer counts only).
    PullingImage,
    Downloading,
    Unpacking,
    Ready,
    Failed,
}

/// Dedicated-server setup as reported in [`WorldStatus`].
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Setup {
    pub state: SetupState,
    pub version: Option<String>,
    pub bytes_done: u64,
    pub bytes_total: u64,
    pub layers_done: u32,
    pub layers_total: u32,
    pub eula_accepted: bool,
    pub error: Option<String>,
    /// `native`, `container` or `none`.
    pub runtime: String,
    pub reason: Option<String>,
}

/// Status of the open local world; `error` is a short reason with no local paths.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct WorldStatus {
    pub state: WorldState,
    pub world_id: Option<String>,
    /// Backend of the open world.
    pub backend: Option<Backend>,
    pub paused: bool,
    /// False when the open world's server cannot pause (BDS).
    pub pause_supported: bool,
    pub error: Option<String>,
    pub setup: Option<Setup>,
    pub backend_unavailable_reason: Option<UnavailableReason>,
    /// The running server's player limit, the host included.
    pub max_players: Option<u32>,
}

/// Local-world preferences kept beside the worlds.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct Prefs {
    pub docker_prompt_dismissed: bool,
}

/// Changes to [`Prefs`]; `redetect` re-probes for Docker before answering.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct PrefsUpdate {
    pub docker_prompt_dismissed: Option<bool>,
    pub redetect: bool,
}
